use std::fs

fn emit(text: string, number: bool, counter: int) -> int {
    let mut n = counter
    if number {
        for line in text.lines() {
            n = n + 1
            let s = n.to_string()
            let mut pad = ""
            let mut i = s.len() as int
            while i < 6 {
                pad = pad + " "
                i = i + 1
            }
            println("{}{}\t{}", pad, s, line)
        }
    } else {
        print("{}", text)
    }
    n
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in std::env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter = 0
    let mut status = 0
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f.clone()) {
                Ok(text) => {
                    counter = emit(text, number, counter)
                }
                Err(_) => {
                    println("cat: {}: No such file", f)
                    status = 1
                }
            }
        }
    }
    if status != 0 {
        std::process::exit(status)
    }
}

